function solve(s) {
  const n = s.length;
  const dp = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(false));
  for (let i = 0; i <= n; i++) dp[i][i] = true;
  for (let len = 1; len <= n; len++) {
    for (let i = 0; i + len <= n; i++) {
      const j = i + len;
      let ok = false;
      if (s[i] === '*' && dp[i + 1][j]) ok = true;
      if (!ok && (s[i] === '(' || s[i] === '*')) {
        for (let k = i + 2; k <= j; k++) {
          const closer = s[k - 1];
          if ((closer === ')' || closer === '*') && dp[i + 1][k - 1] && dp[k][j]) {
            ok = true;
            break;
          }
        }
      }
      dp[i][j] = ok;
    }
  }
  return dp[0][n];
}

function solve(s) {
  let lo = 0;
  let hi = 0;
  for (const ch of s) {
    if (ch === '(') {
      lo++;
      hi++;
    } else if (ch === ')') {
      lo = Math.max(lo - 1, 0);
      hi--;
    } else {
      lo = Math.max(lo - 1, 0);
      hi++;
    }
    if (hi < 0) return false;
  }
  return lo === 0;
}
